def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Identify horizontal bars and fill single-cell gaps within them.
    bar_rows = set()
    horizontal_events = {}
    for r in range(h):
        if sum(v != 0 for v in grid[r]) < 3:
            continue
        bar_rows.add(r)
        for c in range(1, w - 1):
            if grid[r][c] == 0 and grid[r][c - 1] != 0 and grid[r][c - 1] == grid[r][c + 1]:
                color = grid[r][c - 1]
                out[r][c] = color
                horizontal_events.setdefault(c, []).append((r, color))

    # At each gap column, extend the horizontal bars upward in successive
    # segments. A vertical colored marker supplies the final lower segment.
    for c, events in horizontal_events.items():
        markers = [(r, color, True) for r, color in events]
        for r in range(h):
            if r not in bar_rows and grid[r][c] != 0:
                markers.append((r, grid[r][c], False))
                break

        markers.sort(key=lambda x: x[0])
        # If two kinds of marker share a row, the horizontal bar takes priority.
        merged = {}
        for r, color, is_horizontal in markers:
            if r not in merged or is_horizontal:
                merged[r] = color

        prev = -1
        for r, color in sorted(merged.items()):
            for rr in range(prev + 1, r + 1):
                out[rr][c] = color
            prev = r

        # A vertical marker continues to the bottom edge.
        if any(not is_horizontal for _, _, is_horizontal in markers):
            color = merged[max(merged)]
            for rr in range(prev + 1, h):
                out[rr][c] = color

    return out
